void ui_show_msg_info(void) {
  lv_obj_remove_flag(lv_obj_get_parent(ui_msg_info), LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(lv_obj_get_parent(ui_msg_info));
}

void ui_hide_msg_info(void) {
  lv_obj_add_flag(lv_obj_get_parent(ui_msg_info), LV_OBJ_FLAG_HIDDEN);
}

void ui_init(void) {
  ui__theme_init();
  ui__scr_home_create();
  ui__scr_inputs_create();
  ui__scr_display_create();
  ui__scr_structure_create();
  ui__scr_more_create();
  ui__current = UI_SCREEN_HOME;
  lv_screen_load(ui_scr_home);
  lv_timer_create(ui__statusbar_tick, 1000, NULL);
  ui__statusbar_tick(NULL);
}
